def iter_tokens(
    self, tokens: Iterable[Dict[str, Any]], state: BlockState
) -> Iterable[str]:
    prev = None
    for tok in tokens:
        # ignore blank line
        if tok['type'] == 'blank_line':
            continue
        tok['prev'] = prev
        prev = tok
        yield self.render_token(tok, state)
